using System.Globalization;

namespace CheckoutPricing.UnitTest.Features.Discount;

internal static class Money
{
    public static int Cents(string eur) =>
        (int)(decimal.Parse(eur, CultureInfo.InvariantCulture) * 100m);

    public static string? Code(string code) => code == "none" ? null : code;
}

using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private static LoyaltyDiscountQuote Quote(string subtotal, LoyaltyTier tier, string? code = null) =>
        new CalculateLoyaltyDiscount().Handle(
            new CalculateLoyaltyDiscountQuery(Money.Cents(subtotal), tier, code));

    private static void AssertQuote(LoyaltyDiscountQuote quote, string discount, string total)
    {
        Assert.Equal(Money.Cents(discount), quote.DiscountCents);
        Assert.Equal(Money.Cents(total), quote.TotalCents);
    }

    // S1 Member receives the loyalty discount of their tier
    [Theory]
    [InlineData(LoyaltyTier.Bronze, "5.00", "95.00")]
    [InlineData(LoyaltyTier.Silver, "10.00", "90.00")]
    [InlineData(LoyaltyTier.Gold, "15.00", "85.00")]
    public void S1_MemberReceivesTheLoyaltyDiscountOfTheirTier(LoyaltyTier tier, string discount, string total) =>
        AssertQuote(Quote("100.00", tier), discount, total);

    // S2 Member's loyalty discount never exceeds 20.00 EUR
    [Theory]
    [InlineData("200.00", LoyaltyTier.Gold, "20.00", "180.00")]
    [InlineData("300.00", LoyaltyTier.Silver, "20.00", "280.00")]
    [InlineData("120.00", LoyaltyTier.Gold, "18.00", "102.00")]
    public void S2_LoyaltyDiscountNeverExceedsTwentyEuros(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(Quote(subtotal, tier), discount, total);

    // S3 Gold member gets no loyalty discount under a 30.00 EUR subtotal
    [Theory]
    [InlineData("29.99", "0.00", "29.99")]
    [InlineData("30.00", "4.50", "25.50")]
    public void S3_NoLoyaltyDiscountUnderThirtyEurosSubtotal(string subtotal, string discount, string total) =>
        AssertQuote(Quote(subtotal, LoyaltyTier.Gold), discount, total);

    // S4 Member takes 5.00 EUR off with WELCOME5 after the loyalty discount
    [Theory]
    [InlineData("100.00", LoyaltyTier.Silver, "15.00", "85.00")]
    [InlineData("20.00", LoyaltyTier.Bronze, "5.00", "15.00")]
    public void S4_Welcome5TakesFiveEurosOffAfterTheLoyaltyDiscount(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, total);

    // S5 Member's WELCOME5 is never capped with the loyalty discount
    [Theory]
    [InlineData("200.00", LoyaltyTier.Gold, "25.00", "175.00")]
    [InlineData("300.00", LoyaltyTier.Silver, "25.00", "275.00")]
    public void S5_CapAppliesToLoyaltyDiscountOnlyNeverToWelcome5(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, total);

    // S6 Member uses a promo code whatever its case
    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code) =>
        Assert.Equal(Money.Cents("15.00"), Quote("100.00", LoyaltyTier.Silver, code).DiscountCents);

    // S7 Member takes 10 % off what is left with SUMMER10, at most 15.00 EUR
    [Theory]
    [InlineData("100.00", LoyaltyTier.Silver, "19.00", "81.00")]
    [InlineData("300.00", LoyaltyTier.Bronze, "30.00", "270.00")]
    [InlineData("20.00", LoyaltyTier.Gold, "2.00", "18.00")]
    public void S7_Summer10TakesTenPercentOffWhatIsLeftAtMostFifteenEuros(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(Quote(subtotal, tier, "SUMMER10"), discount, total);

    // S8 Member's unknown promo code is ignored
    [Fact]
    public void S8_UnknownPromoCodeIsIgnored() =>
        AssertQuote(Quote("100.00", LoyaltyTier.Silver, "SPRING"), "10.00", "90.00");

    // S9 Platinum member receives a 20 % loyalty discount
    [Theory]
    [InlineData("100.00", "20.00", "80.00")]
    [InlineData("50.00", "10.00", "40.00")]
    [InlineData("200.00", "20.00", "180.00")]
    public void S9_PlatinumMembersReceiveTwentyPercentLoyaltyDiscount(string subtotal, string discount, string total) =>
        AssertQuote(Quote(subtotal, LoyaltyTier.Platinum), discount, total);

    // S10 Member's discount never exceeds the subtotal
    [Theory]
    [InlineData("4.00", LoyaltyTier.Bronze, "4.00")]
    [InlineData("3.00", LoyaltyTier.Gold, "3.00")]
    public void S10_DiscountNeverExceedsTheSubtotal(string subtotal, LoyaltyTier tier, string discount) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, "0.00");
}

using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class CalculateShippingFeeAcceptanceTests
{
    private static int Fee(string total, LoyaltyTier tier, bool express = false) =>
        new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(Money.Cents(total), tier, express));

    // S11 Member ships standard for free from 50.00 EUR payable
    [Theory]
    [InlineData("49.99", LoyaltyTier.Bronze, "4.90")]
    [InlineData("50.00", LoyaltyTier.Bronze, "0.00")]
    [InlineData("49.99", LoyaltyTier.Silver, "4.90")]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(string total, LoyaltyTier tier, string fee) =>
        Assert.Equal(Money.Cents(fee), Fee(total, tier));

    // S12 Gold and Platinum members never pay standard shipping
    [Theory]
    [InlineData(LoyaltyTier.Gold)]
    [InlineData(LoyaltyTier.Platinum)]
    public void S12_GoldAndPlatinumNeverPayStandardShipping(LoyaltyTier tier) =>
        Assert.Equal(Money.Cents("0.00"), Fee("10.00", tier));

    // S13 Only Platinum members ship express for free
    [Theory]
    [InlineData("100.00", LoyaltyTier.Bronze, "9.90")]
    [InlineData("10.00", LoyaltyTier.Gold, "9.90")]
    [InlineData("10.00", LoyaltyTier.Platinum, "0.00")]
    public void S13_ExpressShippingIsFreeForPlatinumOnly(string total, LoyaltyTier tier, string fee) =>
        Assert.Equal(Money.Cents(fee), Fee(total, tier, express: true));
}

using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class QuoteCheckoutAcceptanceTests
{
    // S14 Member's checkout quote adds shipping to the payable total
    [Theory]
    [InlineData("100.00", LoyaltyTier.Silver, "WELCOME5", "standard", "85.00", "0.00", "85.00")]
    [InlineData("50.00", LoyaltyTier.Bronze, "none", "standard", "47.50", "4.90", "52.40")]
    [InlineData("200.00", LoyaltyTier.Platinum, "SUMMER10", "express", "165.00", "0.00", "165.00")]
    [InlineData("20.00", LoyaltyTier.Gold, "none", "express", "20.00", "9.90", "29.90")]
    public void S14_CheckoutQuoteAddsShippingToThePayableTotal(
        string subtotal, LoyaltyTier tier, string code, string shipping, string payable, string fee, string total)
    {
        var quote = new QuoteCheckout().Handle(
            new QuoteCheckoutQuery(Money.Cents(subtotal), tier, Money.Code(code), shipping == "express"));

        Assert.Equal(Money.Cents(payable), quote.PayableCents);
        Assert.Equal(Money.Cents(fee), quote.ShippingCents);
        Assert.Equal(Money.Cents(total), quote.TotalCents);
    }
}

